-- =====================================================================================
-- Catalogue de démonstration : catégories rangées en rayons, pièces auto, accessoires et
-- produits d'entretien, en français, néerlandais et anglais.
--
-- Prix fictifs, fixés TVA comprise au taux de 21 %. Le prix hors TVA de chaque article est
-- celui qui redonne exactement le prix affiché, au cent près. Noms génériques, sans marque.
--
-- Les catégories et les articles déjà semés (V10, V900) gardent leur code : les commandes
-- et interventions de la graine les référencent. Une ligne qu'un administrateur a modifiée
-- (updated_by renseigné par un autre que la graine) n'est pas touchée, un article déjà
-- présent n'est pas inséré une seconde fois.
--
-- La catégorie Atelier est désactivée : ses articles n'entrent que dans la composition des
-- forfaits et ne se vendent pas seuls. La batterie y passe, posée par la prestation de
-- remplacement. L'huile en bidon de V900 est désactivée : une huile vendue seule attend le
-- lot des articles réglementés, comme les autres produits écartés de ce catalogue.
--
-- Traductions écrites par le développeur, à relire par un locuteur.
-- =====================================================================================

UPDATE categorie c
SET libelle = v.fr, libelle_nl = v.nl, libelle_en = v.en, rayon = v.rayon, ordre = v.ordre,
    actif = v.actif, updated_by = 'demo'
FROM (VALUES
          ('P_FILTRES', 'PIECES_AUTO', 'Filtres', 'Filters', 'Filters', 7, TRUE),
          ('P_FREINAGE', 'PIECES_AUTO', 'Pièces de freinage', 'Remonderdelen', 'Brake parts', 8, TRUE),
          ('P_BATTERIE', 'PIECES_AUTO', 'Allumage et électricité', 'Ontsteking en elektriciteit', 'Ignition and electrics', 9, TRUE),
          ('P_MOTEUR', 'PIECES_AUTO', 'Distribution et moteur', 'Distributie en motor', 'Timing and engine', 10, TRUE),
          ('P_SUSPENSION', 'PIECES_AUTO', 'Suspension et direction', 'Ophanging en stuurinrichting', 'Suspension and steering', 11, TRUE),
          ('P_ECLAIRAGE', 'PIECES_AUTO', 'Éclairage et essuyage', 'Verlichting en ruitenwissers', 'Lighting and wipers', 12, TRUE),
          ('P_PNEUS', 'PIECES_AUTO', 'Pneumatiques et roues', 'Banden en wielen', 'Tyres and wheels', 13, TRUE),
          ('P_ECHAPPEMENT', 'PIECES_AUTO', 'Échappement', 'Uitlaat', 'Exhaust', 14, TRUE),
          ('P_HUILE', 'PIECES_AUTO', 'Atelier', 'Werkplaats', 'Workshop', 15, FALSE),
          ('A_INTERIEUR', 'ACCESSOIRES', 'Intérieur', 'Interieur', 'Interior', 20, TRUE),
          ('A_EXTERIEUR', 'ACCESSOIRES', 'Extérieur et transport', 'Exterieur en vervoer', 'Exterior and transport', 21, TRUE),
          ('A_SECURITE', 'ACCESSOIRES', 'Sécurité', 'Veiligheid', 'Safety', 22, TRUE),
          ('A_HIVER', 'ACCESSOIRES', 'Hiver', 'Winter', 'Winter', 23, TRUE),
          ('E_EXTERIEUR', 'ENTRETIEN', 'Nettoyage extérieur', 'Buitenreiniging', 'Exterior cleaning', 30, TRUE),
          ('E_INTERIEUR', 'ENTRETIEN', 'Nettoyage intérieur', 'Interieurreiniging', 'Interior cleaning', 31, TRUE),
          ('E_NIVEAUX', 'ENTRETIEN', 'Atelier et niveaux', 'Werkplaats en peilen', 'Workshop and fluid levels', 32, TRUE)
     ) AS v(code, rayon, fr, nl, en, ordre, actif)
WHERE c.code = v.code
  AND (c.updated_by IS NULL OR c.updated_by = 'demo');

INSERT INTO categorie (code, libelle, libelle_nl, libelle_en, type, rayon, ordre, actif, created_by, updated_by)
SELECT v.code, v.fr, v.nl, v.en, 'PIECE', v.rayon, v.ordre, v.actif, 'demo', 'demo'
FROM (VALUES
          ('P_FILTRES', 'PIECES_AUTO', 'Filtres', 'Filters', 'Filters', 7, TRUE),
          ('P_FREINAGE', 'PIECES_AUTO', 'Pièces de freinage', 'Remonderdelen', 'Brake parts', 8, TRUE),
          ('P_BATTERIE', 'PIECES_AUTO', 'Allumage et électricité', 'Ontsteking en elektriciteit', 'Ignition and electrics', 9, TRUE),
          ('P_MOTEUR', 'PIECES_AUTO', 'Distribution et moteur', 'Distributie en motor', 'Timing and engine', 10, TRUE),
          ('P_SUSPENSION', 'PIECES_AUTO', 'Suspension et direction', 'Ophanging en stuurinrichting', 'Suspension and steering', 11, TRUE),
          ('P_ECLAIRAGE', 'PIECES_AUTO', 'Éclairage et essuyage', 'Verlichting en ruitenwissers', 'Lighting and wipers', 12, TRUE),
          ('P_PNEUS', 'PIECES_AUTO', 'Pneumatiques et roues', 'Banden en wielen', 'Tyres and wheels', 13, TRUE),
          ('P_ECHAPPEMENT', 'PIECES_AUTO', 'Échappement', 'Uitlaat', 'Exhaust', 14, TRUE),
          ('P_HUILE', 'PIECES_AUTO', 'Atelier', 'Werkplaats', 'Workshop', 15, FALSE),
          ('A_INTERIEUR', 'ACCESSOIRES', 'Intérieur', 'Interieur', 'Interior', 20, TRUE),
          ('A_EXTERIEUR', 'ACCESSOIRES', 'Extérieur et transport', 'Exterieur en vervoer', 'Exterior and transport', 21, TRUE),
          ('A_SECURITE', 'ACCESSOIRES', 'Sécurité', 'Veiligheid', 'Safety', 22, TRUE),
          ('A_HIVER', 'ACCESSOIRES', 'Hiver', 'Winter', 'Winter', 23, TRUE),
          ('E_EXTERIEUR', 'ENTRETIEN', 'Nettoyage extérieur', 'Buitenreiniging', 'Exterior cleaning', 30, TRUE),
          ('E_INTERIEUR', 'ENTRETIEN', 'Nettoyage intérieur', 'Interieurreiniging', 'Interior cleaning', 31, TRUE),
          ('E_NIVEAUX', 'ENTRETIEN', 'Atelier et niveaux', 'Werkplaats en peilen', 'Workshop and fluid levels', 32, TRUE)
     ) AS v(code, rayon, fr, nl, en, ordre, actif)
WHERE NOT EXISTS (SELECT 1 FROM categorie c WHERE c.code = v.code);

INSERT INTO categorie (code, libelle, libelle_nl, libelle_en, type, ordre, created_by, updated_by)
SELECT v.code, v.fr, v.nl, v.en, 'SERVICE', v.ordre, 'demo', 'demo'
FROM (VALUES
          ('CLIMATISATION', 'Climatisation', 'Airconditioning', 'Air conditioning', 40),
          ('MOTEUR', 'Distribution et moteur', 'Distributie en motor', 'Timing and engine', 41)
     ) AS v(code, fr, nl, en, ordre)
WHERE NOT EXISTS (SELECT 1 FROM categorie c WHERE c.code = v.code);

-- Articles déjà semés par V900 : textes, prix, stock et catégorie mis au niveau du catalogue.
